@Component("agency-handler")
@ProcessingGroup("agency-processing-group")
public class AgencyEventHandler {
	
	// core constructor
	AgencyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAgencyEvent
     */
    @EventHandler
    public void handle( CreateAgencyEvent event) {
        entityManager.persist(new Agency(event.getAgencyId(), event.getName(), event.getLegalName(), event.getHeadquartersCountry(), event.getWebsite(), event.getAdvertisers(), event.getTeams(), event.getUsers(), event.getInsertionOrders()));
    }

    /*
     * @param	event UpdateAgencyEvent
     */
    @EventHandler
    public Agency handle( UpdateAgencyEvent event) {
    	entityManager.merge(new Agency(event.getAgencyId(), event.getName(), event.getLegalName(), event.getHeadquartersCountry(), event.getWebsite(), event.getAdvertisers(), event.getTeams(), event.getUsers(), event.getInsertionOrders()));
    }
    
    /*
     * @param	event DeleteAgencyEvent
     */
    @EventHandler
    public void on( DeleteAgencyEvent event) {
    	Agency entity = new Agency();
   
    	// ------------------------------------------
    	// apply the AgencyId
    	// ------------------------------------------
    	entity.setAgencyId( event.getAgencyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AgencyRepository agencyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AgencyEventHandler.class.getName());

}
